(() => {
'use strict';
const APP_VERSION='3.0.0', PREVIEW_ONLY=/\/preview-v3\.html$/i.test(location.pathname), SURL=window.APP_CONFIG?.SUPABASE_URL||'', SKEY=window.APP_CONFIG?.SUPABASE_PUBLISHABLE_KEY||'', READY=!!(window.supabase&&SURL.startsWith('https://')&&SKEY&&!SKEY.includes('YOUR_'));
const authStorage={getItem(k){return localStorage.getItem(k)??sessionStorage.getItem(k)},setItem(k,v){if(localStorage.getItem('thawaqV3Remember')==='0'){sessionStorage.setItem(k,v);localStorage.removeItem(k)}else{localStorage.setItem(k,v);sessionStorage.removeItem(k)}},removeItem(k){localStorage.removeItem(k);sessionStorage.removeItem(k)}};
const sup=READY?window.supabase.createClient(SURL,SKEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,storage:authStorage}}):null;
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)], escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=x=>Number(x||0), decimal=x=>Number.isFinite(Number(x))?Number(x):0, money=x=>`${num(x).toLocaleString('ar-AE',{maximumFractionDigits:2})} د.إ`, day=x=>x?new Date(x).toLocaleDateString('ar-AE',{day:'numeric',month:'long',year:'numeric'}):'—';
const dt=x=>x?new Date(x).toLocaleDateString('ar-AE',{day:'numeric',month:'short',year:'numeric'}):'—', iconType=t=>t==='tea'?'🫖':t==='cafe'?'☕':'🍽️', labelType=t=>t==='tea'?'شاي':t==='cafe'?'كوفي':'مطعم';
const pathIcon={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m15.4 8.6-2 4.8-4.8 2 2-4.8z"/>',book:'<path d="M4 5h6a3 3 0 0 1 3 3v12H7a3 3 0 0 0-3 1zM20 5h-4a3 3 0 0 0-3 3v12h4a3 3 0 0 1 3 1z"/>',chart:'<path d="M3 20h18M7 16V9M12 16V4M17 16v-5"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',plus:'<path d="M12 5v14M5 12h14"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19 12a7 7 0 0 0-.2-1.4l1.8-1.4-2-3.4-2.1.8a8 8 0 0 0-2.4-1.4L13.7 3h-3.4l-.4 2.2a8 8 0 0 0-2.4 1.4l-2.1-.8-2 3.4 1.8 1.4a7 7 0 0 0 0 2.8l-1.8 1.4 2 3.4 2.1-.8a8 8 0 0 0 2.4 1.4l.4 2.2h3.4l.4-2.2a8 8 0 0 0 2.4-1.4l2.1.8 2-3.4-1.8-1.4A7 7 0 0 0 19 12z"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',arrow:'<path d="m15 18-6-6 6-6"/>',share:'<path d="M12 16V3m-5 5 5-5 5 5M5 14v6a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-6"/>',heart:'<path d="M20.8 8.6a5 5 0 0 0-8.8-2.9 5 5 0 0 0-8.8 2.9c-.4 4.1 8.8 10.2 8.8 10.2s9.2-6.1 8.8-10.2z"/>',filter:'<path d="M4 6h16M7 12h10M10 18h4"/>',refresh:'<path d="M20 11a8 8 0 1 0-2.2 6.3M20 4v7h-7"/>',camera:'<path d="M4 7h4l2-3h4l2 3h4v13H4z"/><circle cx="12" cy="13" r="4"/>',check:'<path d="m5 12 4 4L19 6"/>',back:'<path d="m9 18 6-6-6-6"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0z"/><circle cx="12" cy="10" r="2"/>',trash:'<path d="M3 6h18M8 6V4h8v2M6 6l1 15h10l1-15"/>',edit:'<path d="m3 17 1 4 4-1L20 8l-4-4z"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 18v3h16v-3"/>'};
const ico=(key,size=19)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round" stroke-linecap="round" aria-hidden="true">${pathIcon[key]||pathIcon.home}</svg>`;
const state={tab:'home',session:null,me:null,people:[],places:[],visits:[],items:[],likes:new Set(),favLoaded:false,filter:{q:'',type:'all',city:'all',sort:'recent'},diaryFilter:'all',openedPlace:null,busy:false,online:navigator.onLine,live:'',shareSlug:new URLSearchParams(location.search).get('share'),release:null,channels:[],needsRefresh:false,publicMode:false};
const STORAGE_DRAFT='thawaq-v3-draft',FAV_KEY='thawaq-v3-local-likes',HINT='هذه نسخة معاينة مستقلة ولا تغيّر ذواق الرسمي';
function alertToast(t){const region=$('#toastRegion');if(!region)return;region.innerHTML=`<div class="toast">${escape(t)}</div>`;clearTimeout(window.__twToast);window.__twToast=setTimeout(()=>region.replaceChildren(),3200)}
function getOwner(p){return state.people.find(x=>x.id===p.owner_id)}
function own(p){return !!state.me&&(p.owner_id===state.me.id||state.me.role==='admin')}
function mine(){return state.places.filter(p=>p.owner_id===state.me?.id)}
function placeVisits(id){return state.visits.filter(v=>v.place_id===id).sort((a,b)=>new Date(b.visited_at)-new Date(a.visited_at))}
function visitItems(id){return state.items.filter(i=>i.visit_id===id)}
function placeItems(id){return state.items.filter(i=>i.place_id===id)}
function rating(p){if(p.rating_override!==null&&p.rating_override!==undefined&&p.rating_override!=='')return num(p.rating_override);const rows=placeItems(p.id);return rows.length?rows.reduce((s,x)=>s+num(x.rating),0)/rows.length:0}
function subtotal(v){return visitItems(v.id).reduce((s,i)=>s+num(i.price),0)}
function visitTotal(v){const base=v.total_override!==null&&v.total_override!==''?num(v.total_override):subtotal(v);return base*(v.tax_enabled?1+num(v.tax_rate||5)/100:1)}
function shareUrl(p){const slug=p.public_slug||p.username;return READY?`${SURL}/functions/v1/p/${encodeURIComponent(slug)}`:`${location.origin}${location.pathname}?share=${encodeURIComponent(slug)}`}
function prettyUrl(p){return `thawaq.app/${escape(p.public_slug||p.username||'my-page')}`}
function userOfShare(){const slug=state.shareSlug?.toLowerCase();return state.people.find(u=>u.public_slug?.toLowerCase()===slug||u.username?.toLowerCase()===slug)}
function profileUrl(p){return `${location.pathname}?share=${encodeURIComponent(p.public_slug||p.username)}`}
function btn(text,act,cls='outline',extras=''){return `<button class="btn ${cls}" type="button" data-action="${act}" ${extras}>${text}</button>`}
function requiredLogin(){if(!state.me){openModal('login');return false}return true}
function admin(){return state.me?.role==='admin'}
function lastVisit(p){return placeVisits(p.id)[0]}
function allCities(){return [...new Set(state.places.map(p=>p.city).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ar'))}
function getFilters(base){let rows=base.filter(p=>state.filter.type==='all'||p.type===state.filter.type).filter(p=>state.filter.city==='all'||p.city===state.filter.city);const q=state.filter.q.trim().toLocaleLowerCase();if(q)rows=rows.filter(p=>(p.name+' '+p.city+' '+p.notes+' '+(getOwner(p)?.display_name||'')+' '+placeItems(p.id).map(x=>x.name).join(' ')).toLocaleLowerCase().includes(q));const sorter=state.filter.sort;if(sorter==='high')rows.sort((a,b)=>rating(b)-rating(a));else if(sorter==='alpha')rows.sort((a,b)=>a.name.localeCompare(b.name,'ar'));else if(sorter==='visits')rows.sort((a,b)=>placeVisits(b.id).length-placeVisits(a.id).length);else rows.sort((a,b)=>new Date(b.updated_at||b.created_at)-new Date(a.updated_at||a.created_at));return rows}
function installNavigation(){if(!admin()){ $('#rail').classList.add('hidden');$('#bottomNav').innerHTML='';return;}const nav=[['home','الرئيسية','home'],['discover','اكتشف','compass'],['diary','يومياتي','book'],['insights','إحصاءاتي','chart'],['account','حسابي','user']];if(state.publicMode){$('#rail').classList.add('hidden');$('#bottomNav').innerHTML='';return}$('#rail').classList.remove('hidden');$('#railNav').innerHTML=nav.map(([id,title,ic])=>`<button class="nav-button ${state.tab===id?'active':''}" data-tab="${id}">${ico(ic)}<span>${title}</span></button>`).join('')+`<button class="nav-button" data-action="new-place">${ico('plus')}<span>تجربة جديدة</span></button>`;$('#bottomNav').innerHTML=nav.slice(0,4).map(([id,title,ic])=>`<button class="bottom-button ${state.tab===id?'active':''}" data-tab="${id}">${ico(ic)}<span>${title}</span></button>`).join('')+`<button class="bottom-button ${state.tab==='account'?'active':''}" data-tab="account">${ico('user')}<span>حسابي</span></button>`}
function updateHeader(){const h=$('#headerSubtitle');h.textContent=state.publicMode?'صفحة تجارب عامة':state.me?'كل مكان له حكاية':'تجارب تستحق التذكر';$('#railSync').textContent=state.online?'● المزامنة متصلة':'● دون اتصال · الحفظ مؤجل';let avatar=$('#avatarBtn');avatar.innerHTML=state.me?.avatar_url?`<img src="${escape(state.me.avatar_url)}" alt=""/>`:escape(state.me?.display_name?.slice(0,1)||'ذ');}
function render(){installNavigation();updateHeader();const root=$('#root');if(PREVIEW_ONLY&&state.me?.role!=='admin'){$('#rail').classList.add('hidden');$('#bottomNav').classList.add('hidden');root.innerHTML=loginGate('معاينة ذواق 3.0 للمالك فقط','سجّل دخولك بحساب المالك لاختبار التصميم الجديد قبل تعميمه. المستخدمون يبقون على النسخة الرسمية.');return;}if(!state.online)root.innerHTML='<div class="offline-banner">أنت بدون إنترنت. يمكنك قراءة البيانات المحمّلة وحفظ مسودة التقييم، وستحتاج إلى اتصال لحفظها في حسابك.</div>';
 const html=state.publicMode?renderPublicProfile():state.tab==='home'?home():state.tab==='discover'?discover():state.tab==='diary'?diary():state.tab==='insights'?insights():state.tab==='account'?account():home();root.innerHTML=(!state.online?'<div class="offline-banner">أنت دون اتصال. البيانات المعروضة آخر بيانات تمت مزامنتها؛ مسوداتك محفوظة محليًا.</div>':'')+html;
 window.scrollTo({top:0,behavior:'instant'});
}
function featuredPhoto(p){if(p.cover_url)return `<img loading="lazy" src="${escape(p.cover_url)}" alt="${escape(p.name)}" onerror="this.remove()"/>`;return `<div class="fallback-mark">${iconType(p.type)}</div>`}
function placeTile(p){const visits=placeVisits(p.id),r=rating(p),fav=state.likes.has(p.id),o=getOwner(p);return `<article class="card place-tile" tabindex="0" data-place="${escape(p.id)}" aria-label="فتح ${escape(p.name)}"><div class="place-cover ${escape(p.type)}">${featuredPhoto(p)}<span class="float-pill">${iconType(p.type)} ${labelType(p.type)}</span><button class="fav-button ${fav?'active':''}" type="button" title="${fav?'إزالة من المفضلة':'إضافة للمفضلة'}" data-action="favorite" data-id="${escape(p.id)}">${fav?'♥':'♡'}</button></div><div class="place-content"><h3>${escape(p.name)}</h3><div class="place-meta">${ico('pin',13)} ${escape(p.city)} ${o&&o.id!==state.me?.id?`· ${escape(o.display_name)}`:''}</div><div class="place-bottom"><span class="rating">${r?'★ '+r.toFixed(1):'جديد'}</span><span>${visits.length} زيارات · ${placeItems(p.id).length} أصناف</span></div></div></article>`}
function stat(k,v,unit=''){return `<div class="card stat-tile"><small>${k}</small><strong>${v}<span class="unit">${unit}</span></strong></div>`}
function hero(){const n=state.me?.display_name?.split(' ')[0];return `<section class="hero"><div><div class="eyebrow"><span class="dot"></span>مكانك لتوثيق اللقمة الحلوة</div><h1>${n?'حيّاك يا '+escape(n)+' 👋':'أهلًا بك في ذواق ✨'}</h1><p>كل زيارة، كل قهوة، وكل طبق عجبك أو ما عجبك… خليها في مكان مرتب ترجع له متى ما بغيت.</p><div class="hero-buttons">${btn(ico('plus',19)+' أضف تجربة','new-place','primary')}${btn(ico('compass',17)+' اكتشف الأماكن','go-discover','outline')}</div></div><div class="hero-illustration"><span class="float-star">✦</span><svg viewBox="0 0 120 120" fill="none" stroke="currentColor" stroke-width="4" stroke-linecap="round"><path d="M23 62h74M26 61c0 21 16 37 34 37s34-16 34-37"/><path d="M61 19c-12 14 12 17 0 31M43 25c-10 10 8 13 0 22M79 25c-10 10 8 13 0 22"/><path d="M38 100h44"/></svg></div></section>`}
function empty(title,subtitle,action='new-place',text='أضف أول تجربة'){return `<div class="card empty-state"><div class="empty-symbol">✦</div><h3>${title}</h3><p>${subtitle}</p>${action?btn(ico('plus')+' '+text,action,'primary'):''}</div>`}
function home(){const ownPlaces=mine();const recent=getFilters(state.places).slice(0,6);const totalVisits=state.visits.filter(v=>ownPlaces.some(p=>p.id===v.place_id));const r=ownPlaces.map(rating).filter(Boolean);let top=ownPlaces.filter(p=>rating(p)>0).sort((a,b)=>rating(b)-rating(a)).slice(0,3);return `${hero()}<section class="stat-row">${stat('أماكني',ownPlaces.length)}${stat('زياراتي',totalVisits.length)}${stat('متوسط تقييمي',r.length?(r.reduce((a,b)=>a+b,0)/r.length).toFixed(1):'—','/ 5')}${stat('أصنافي',state.items.filter(i=>i.owner_id===state.me?.id).length)}</section><section class="section-header"><div><h2>تجارب تستاهل المشاركة</h2><p>آخر الأماكن المضافة على ذواق</p></div>${btn('كل الأماكن '+ico('arrow',17),'go-discover','ghost sm')}</section>${recent.length?`<div class="place-grid">${recent.map(placeTile).join('')}</div>`:empty('أول تجربة تبدأ من هنا','ما في تقييمات منشورة حتى الآن. جرب أضف مكانك المفضل وصوّر طلبك، والتفاصيل بنرتبها لك.')}<section class="section-header"><div><h2>أماكنك المميزة</h2><p>أعلى تقييماتك الخاصة</p></div></section>${top.length?`<div class="place-grid">${top.map(placeTile).join('')}</div>`:`<div class="card card-pad" style="display:flex;align-items:center;justify-content:space-between;gap:15px"><div><b>قيّم طلبًا واستكشف ذوقك ⭐</b><p class="muted-small" style="margin:5px 0 0">بتظهر أفضل تجاربك تلقائيًا لما تضيف أول صنف وتقييم.</p></div>${btn('ابدأ','new-place','soft')}</div>`}`}
function filterBar(){const q=escape(state.filter.q);return `<div class="filter-stack"><div class="search-wrap">${ico('search')}<input id="searchPlaces" type="search" placeholder="ابحث عن مكان، مدينة، أو صنف…" value="${q}" autocomplete="off" aria-label="البحث عن مكان"/></div><select class="select-native" id="cityFilter" aria-label="اختيار المدينة"><option value="all">كل المدن</option>${allCities().map(c=>`<option ${state.filter.city===c?'selected':''} value="${escape(c)}">${escape(c)}</option>`).join('')}</select><select class="select-native" id="sortFilter" aria-label="الترتيب"><option value="recent" ${state.filter.sort==='recent'?'selected':''}>الأحدث</option><option value="high" ${state.filter.sort==='high'?'selected':''}>الأعلى تقييمًا</option><option value="visits" ${state.filter.sort==='visits'?'selected':''}>الأكثر زيارة</option><option value="alpha" ${state.filter.sort==='alpha'?'selected':''}>حسب الاسم</option></select></div><div class="chip-row">${[['all','الكل ✨'],['restaurant','🍽️ مطاعم'],['cafe','☕ كوفيات'],['tea','🫖 شاي']].map(([id,v])=>`<button data-type="${id}" class="chip ${state.filter.type===id?'active':''}">${v}</button>`).join('')}</div>`}
function discover(){const records=getFilters(state.places);return `<div class="eyebrow">DISCOVER THAWAQ</div><div class="section-header" style="margin:7px 0 4px"><div><h1 style="margin:0">اكتشف على ذوقك</h1><p>أماكن وتجارب حقيقية، من ناس يشاركون رأيهم</p></div>${btn(ico('plus')+' تجربة','new-place','primary sm')}</div>${filterBar()}<p class="muted-small" id="resultsCount">${records.length} مكان في نتائج البحث</p><div class="place-grid" id="filteredGrid">${records.map(placeTile).join('')}</div>${!records.length?empty('ما حصلنا نتيجة','غيّر البحث أو اختر تصنيف ثاني، أو كن أول شخص يضيف هالمكان.','new-place','أضف مكان'):''}`}
function diary(){if(!state.me)return loginGate('يومياتك تنتظرك','سجّل دخولك لتشوف كل زياراتك والأطباق اللي جرّبتها في مكان واحد.');const p=mine(),v=state.visits.filter(x=>x.owner_id===state.me.id).sort((a,b)=>new Date(b.visited_at)-new Date(a.visited_at));const list=state.diaryFilter==='favorites'?p.filter(x=>state.likes.has(x.id)):p;return `<div class="eyebrow">MY FOOD JOURNAL</div><h1 style="margin:5px 0">يومياتك ✍️</h1><p class="muted">كل الأماكن والزيارات التي تستحق التذكر، بترتيبها الحقيقي.</p><div class="two-options" style="margin:23px 0">${btn(ico('plus')+' أضف مكان','new-place','primary')}${btn(ico('heart')+' المفضلة','diary-favs','soft')}</div><div class="chip-row">${[['all','أماكني'],['favorites','المفضلة']].map(([k,vv])=>`<button class="chip ${state.diaryFilter===k?'active':''}" data-diary="${k}">${vv}</button>`).join('')}</div>${list.length?`<div class="place-grid">${list.map(placeTile).join('')}</div>`:empty('صفحتك لسه فاضية','ابدأ بكتابة أول تجربة، وبعدها كل زياراتك بتصير هنا تلقائيًا.')}`}
function loginGate(h,p){return `<div class="welcome"><div class="welcome-story"><div class="eyebrow" style="color:#b9d6bc">THAWAQ / MEMBER</div><div><h1>${h}</h1><p>${p}</p></div><span class="mini-flair">☕ ✦ 🍽️</span></div><div class="welcome-login"><h2>حيّاك 👋</h2><p>الدخول متاح للحسابات التي وافق عليها المالك فقط.</p>${btn('تسجيل الدخول','login','primary wide')}<p class="login-note" style="margin-top:15px">مو مسجل؟ اطلب حسابًا من صاحب منصة ذواق. التسجيل العام مغلق لحماية المجتمع.</p></div></div>`}
function insights(){if(!state.me)return loginGate('ذوقك بالأرقام','سجّل دخولك لتشوف تحليلات تجاربك وتطور ذائقتك.');const p=mine(),v=state.visits.filter(x=>x.owner_id===state.me.id),i=state.items.filter(x=>x.owner_id===state.me.id),t=v.reduce((s,x)=>s+visitTotal(x),0),stats=[['restaurant','مطاعم'],['cafe','كوفيات'],['tea','محلات شاي']].map(([k,l])=>[l,p.filter(x=>x.type===k).length]);const cities=[...new Set(p.map(x=>x.city))].map(c=>[c,p.filter(x=>x.city===c).length]).sort((a,b)=>b[1]-a[1]);const max=Math.max(1,...cities.map(x=>x[1]));return `<div class="eyebrow">YOUR TASTE, IN NUMBERS</div><h1 style="margin:5px 0">ذوقك بالأرقام 📊</h1><p class="muted">كل إضافة جديدة ترسم صورة أوضح لتجاربك.</p><div class="stat-row">${stat('أماكن',p.length)}${stat('زيارات',v.length)}${stat('إجمالي الفواتير المسجلة',money(t))}${stat('أصناف جرّبتها',i.length)}</div><div class="insights-grid"><section class="card card-pad"><h2>تصنيفاتك المفضلة</h2><p class="muted-small">توزيع الأماكن المسجلة لديك</p><div class="breakdown">${stats.map(([s,n])=>`<div class="breakdown-item"><span>${s}</span><strong>${n}</strong></div>`).join('')}</div></section><section class="card card-pad"><h2>مدنك الأكثر زيارة</h2><p class="muted-small">بناءً على أماكنك المسجلة</p>${cities.length?cities.slice(0,7).map(([name,c])=>`<div class="bar-row"><div class="bar-head"><span>${escape(name)}</span><b>${c}</b></div><div class="bar-track"><div class="bar-fill" style="width:${100*c/max}%"></div></div></div>`).join(''):'<p class="muted-small">ستظهر المدن بعد إضافة أول تجربة.</p>'}</section></div><section class="card card-pad" style="margin-top:15px"><h2>نسخة احتياطية بنقرة واحدة</h2><p class="muted-small">احفظ بيانات حسابك وأماكنك وأصنافك وزياراتك كملف JSON. الصور محفوظة بروابطها، وليس داخل الملف.</p>${btn(ico('download')+' تنزيل نسخة احتياطية','backup','outline')}</section>`}
function account(){if(!state.me)return loginGate('هذا مكانك الخاص','حسابك ومشاركاتك ومفضلاتك وإعداداتك في مكان مرتب وآمن.');const me=state.me;return `<div class="profile-banner card"><div class="profile-avatar">${me.avatar_url?`<img src="${escape(me.avatar_url)}" alt="صورتك"/>`:escape(me.display_name?.slice(0,1)||'ذ')}</div><div class="profile-data"><span class="eyebrow">THAWAQ MEMBER</span><h1>${escape(me.display_name||me.username)}</h1><p>@${escape(me.username)} ${admin()?'<span class="pill gold">مدير المنصة</span>':''}</p><div class="muted-small">${escape(me.bio||'كل مكان يستحق حكاية صغيرة.')}</div></div></div><div class="section-header"><div><h2>حسابي ومشاركتي</h2><p>انشر ذوقك بطريقتك</p></div></div><div class="account-grid"><div class="card account-panel">${ico('book',27)}<div><strong>${mine().length} أماكن</strong><small>تجارب موثقة</small></div></div><div class="card account-panel">${ico('heart',27)}<div><strong>${state.likes.size} مفضلة</strong><small>أماكن محفوظة</small></div></div></div><div class="card card-pad" style="margin-top:14px"><span class="eyebrow">YOUR PUBLIC PAGE</span><h2 style="margin:9px 0">رابط صفحتك في ذواق</h2><div class="share-pretty">${prettyUrl(me)}</div><p class="muted-small" style="margin:12px 0 16px">اسم جميل للعرض داخل التطبيق. عند المشاركة يُستخدم العنوان الحقيقي الذي يعمل عند الآخرين.</p><div class="two-options">${btn(ico('share')+' مشاركة','share-me','primary')}${btn('نسخ الرابط','copy-me','outline')}</div></div><div class="section-header"><h2>الإعدادات</h2></div><div class="settings-menu">${btn(ico('edit')+' تعديل الحساب','edit-profile','outline')}${btn(ico('settings')+' تفضيلات وروابط','settings','outline')}${btn(ico('download')+' نسخة احتياطية','backup','outline')}${admin()?btn(ico('user')+' إدارة المستخدمين','admin-users','outline'):''}${btn('تسجيل الخروج','logout','danger')}</div>`}
function renderPublicProfile(){const u=userOfShare();if(!u||u.is_active===false)return `<div class="card card-pad" style="text-align:center;margin-top:50px"><h2>هالرابط غير متاح</h2><p>يمكن أن صاحبه غيّر رابط المشاركة أو ألغى حسابه.</p>${btn('العودة لذواق','exit-share','primary')}</div>`;const rows=state.places.filter(p=>p.owner_id===u.id);return `<div class="profile-banner card"><div class="profile-avatar">${u.avatar_url?`<img src="${escape(u.avatar_url)}" alt=""/>`:escape(u.display_name?.slice(0,1))}</div><div class="profile-data"><span class="eyebrow">PUBLIC THAWAQ DIARY</span><h1>ذوق ${escape(u.display_name)} ✨</h1><p>${escape(u.bio||'هني تجارب تستاهل المشاركة')}</p></div></div><div class="section-header"><h2>أماكن ${escape(u.display_name)}</h2><span class="pill">${rows.length} مكان</span></div><div class="place-grid">${getFilters(rows).map(placeTile).join('')}</div>${!rows.length?empty('لا توجد تقييمات بعد','صاحب الصفحة ما نشر تجربة إلى الآن.',null):''}`}
function showModal(title,body,subtitle=''){const layer=$('#modalLayer');layer.classList.add('show');layer.innerHTML=`<div class="scrim" data-action="close-modal"></div><div class="modal-dialog" role="dialog" aria-modal="true" aria-label="${escape(title)}"><div class="modal-header"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button type="button" class="modal-close" data-action="close-modal" aria-label="إغلاق">×</button></div>${body}</div>`;$('.modal-dialog',layer)?.scrollTo(0,0)}
function closeModal(){const layer=$('#modalLayer');layer.classList.remove('show');layer.replaceChildren()}
const field=(name,label,type='text',value='',extra='')=>`<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${escape(value)}" ${extra}/></div>`;
function fileInput(id,label){return `<div class="field"><label>${label}</label><label class="file-tile">${ico('camera')} <span>اختر صورة من الألبوم أو صوّر الآن <small>اختياري · JPG, PNG أو HEIC إذا كان مدعومًا</small></span><input id="${id}" name="${id}" type="file" accept="image/*"/></label><img id="${id}Preview" class="photo-preview hidden" alt="معاينة الصورة" /></div>`}
function ratingButtons(value=4.5){return `<div class="field"><label>تقييمك من 5 نجوم</label><div class="star-selector" id="starSelector">${[1,2,3,4,5].map(n=>`<button class="star-button ${n<=Math.round(value)?'selected':''}" type="button" data-star="${n}" aria-label="${n} نجوم">★</button>`).join('')}<strong id="starValue" style="color:#b77e3c">${value.toFixed(1)}/5</strong></div><input type="hidden" id="ratingValue" value="${value}"/></div>`}
function cityOptions(){return `<datalist id="cityChoices">${['أبوظبي','العين','دبي','الشارقة','عجمان','أم القيوين','رأس الخيمة','الفجيرة','الظفرة',...allCities()].filter((v,i,a)=>a.indexOf(v)===i).map(v=>`<option value="${escape(v)}"/>`).join('')}</datalist>`}
function openModal(which,id,extra){if(which==='login')return showModal('دخول ذواق',`<form id="loginForm"><p class="muted-small">الدخول متاح فقط للمستخدمين المعتمدين من المالك.</p>${field('loginIdentifier','البريد الإلكتروني أو اسم المستخدم','text','', 'required autocomplete="username" placeholder="username أو email@example.com"')}${field('loginPassword','كلمة المرور','password','', 'required autocomplete="current-password"')}<label class="radio-label"><input id="loginRemember" type="checkbox" checked/> إبقائي مسجّلًا على هذا الجهاز</label><div class="modal-actions"><button class="btn primary wide" type="submit">تسجيل الدخول</button></div><div class="form-message" id="loginError"></div></form>`,'حسابك خاص وآمن');
 if(which==='place'){if(!requiredLogin())return;let p=state.places.find(x=>x.id===id);if(p&&!own(p))return;const saved=(!p&&localStorage.getItem(STORAGE_DRAFT))?JSON.parse(localStorage.getItem(STORAGE_DRAFT)||'null'):null;return showModal(p?'تعديل المكان':'وثّق تجربة جديدة ✨',`<form id="placeForm" data-id="${escape(p?.id||'')}"><p class="muted-small">${p?'غيّر بيانات المكان بدون التأثير على سجل زياراتك.':'حدد المكان، وإذا تبي سجّل أول صنف من نفس الشاشة.'}</p>${field('placeName','اسم المطعم أو الكوفي','text',p?.name||saved?.name||'','required maxlength="90" placeholder="مثال: جلسة قهوة"')}${field('placeCity','المدينة','text',p?.city||saved?.city||'العين','required list="cityChoices"')}${cityOptions()}<div class="field"><label>التصنيف</label><div class="choice-line">${[['restaurant','🍽️ مطعم'],['cafe','☕ كوفي'],['tea','🫖 شاي']].map(([x,l])=>`<button type="button" class="choice ${(p?.type||saved?.type||'restaurant')===x?'active':''}" data-choice="${x}">${l}</button>`).join('')}</div><input id="placeType" type="hidden" value="${escape(p?.type||saved?.type||'restaurant')}"/></div>${field('placeNotes','انطباعك المختصر — اختياري','text',p?.notes||saved?.notes||'','maxlength="280" placeholder="شو ميّز المكان؟"')}${fileInput('placePhoto',p?'تغيير صورة المكان — اختياري':'صورة المكان — اختياري')}${!p?`<div class="subsection"><strong>تبي تضيف صنف الحين؟</strong><p class="muted-small">اختياري، تقدر ترجع له بعدين.</p>${field('quickItemName','اسم الصنف','text',saved?.quickItem||'','placeholder="مثال: سبانش لاتيه"')}${field('quickItemPrice','السعر بالدرهم','number',saved?.quickPrice||'','min="0" step="0.01" placeholder="0"')}</div>`:''}<div class="modal-actions"><button type="button" class="btn ghost" data-action="close-modal">إلغاء</button><button class="btn primary" type="submit" id="savePlaceBtn">${p?'حفظ التغييرات':'حفظ المكان'}</button></div></form>`,'إضافة سهلة بدون خطوات مربكة')}
 if(which==='item'){if(!requiredLogin())return;const place=state.places.find(p=>p.id===id),visit=state.visits.find(v=>v.id===extra?.visitId),item=state.items.find(i=>i.id===extra?.itemId);if(!place||!own(place)||!visit||visit.place_id!==id)return;return showModal(item?'تعديل الصنف':'أضف صنفًا وقيّمه',`<form id="itemForm" data-place="${escape(id)}" data-visit="${escape(visit.id)}" data-id="${escape(item?.id||'')}"><p class="muted-small">${escape(place.name)} • ${dt(visit.visited_at)}</p>${field('itemName','اسم الطلب','text',item?.name||'','required maxlength="110" placeholder="وش طلبت؟"')}<div class="field-row">${field('itemPrice','السعر (درهم)','number',item?.price??'','required min="0" step="0.01"')}${field('itemNotes','ملاحظتك المختصرة','text',item?.notes||'','maxlength="260" placeholder="وش رأيك فيه؟"')}</div>${ratingButtons(num(item?.rating||4.5))}${fileInput('itemPhoto','صورة الصنف — اختياري')}<div class="modal-actions">${item?btn(ico('trash')+' حذف الصنف','delete-item','danger',`data-id="${escape(item.id)}"`):''}<button type="button" class="btn ghost" data-action="close-modal">إلغاء</button><button type="submit" class="btn primary" id="saveItemBtn">حفظ الصنف</button></div></form>`)}
 if(which==='receipt'){if(!requiredLogin())return;const visit=state.visits.find(v=>v.id===id),place=state.places.find(p=>p.id===visit?.place_id);if(!visit||!own(place))return;return showModal('فاتورة الزيارة',`<form id="receiptForm" data-id="${escape(id)}"><p class="muted-small">${escape(place.name)} · ${dt(visit.visited_at)} · كل زيارة لها فاتورتها المستقلة</p>${field('receiptTotal','الإجمالي قبل الضريبة — اختياري','number',visit.total_override??'','step="0.01" min="0" placeholder="يُحسب من أسعار الأصناف تلقائيًا"')}${fileInput('receiptPhoto','الفاتورة من الألبوم أو الكاميرا')}<label class="radio-label" style="margin:16px 0"><input id="receiptTax" type="checkbox" ${visit.tax_enabled?'checked':''}/> احتساب 5% ضريبة على هذه الزيارة</label>${visit.receipt_url?`<p><a href="${escape(visit.receipt_url)}" target="_blank" rel="noopener" class="card-link">عرض الفاتورة السابقة ↗</a></p>`:''}<div class="modal-actions"><button class="btn ghost" data-action="close-modal" type="button">إلغاء</button><button type="submit" class="btn primary" id="saveReceiptBtn">حفظ الفاتورة</button></div></form>`)}
 if(which==='detail'){const p=state.places.find(x=>x.id===id);if(!p)return;state.openedPlace=p.id;const visits=placeVisits(id),edit=own(p),r=rating(p);return showModal(escape(p.name),`<div class="detail-cover">${featuredPhoto(p)}</div><div class="detail-top"><div><h2>${escape(p.name)}</h2><div class="muted-small">${iconType(p.type)} ${labelType(p.type)} · ${ico('pin',13)} ${escape(p.city)}</div></div><span class="pill gold">${r?'★ '+r.toFixed(1):'لم يقيّم بعد'}</span></div>${p.notes?`<p>${escape(p.notes)}</p>`:''}<div class="choice-line" style="margin:11px 0 18px">${edit?btn(ico('plus')+' زيارة جديدة','add-visit','primary',`data-id="${escape(id)}"`):''}${edit?btn(ico('edit')+' تعديل المكان','edit-place','outline',`data-id="${escape(id)}"`):''}${btn(ico('pin')+' موقعه في الخرائط','maps','soft',`data-id="${escape(id)}"`)}</div><div class="section-header" style="margin:15px 0"><div><h2>سجل الزيارات</h2><p>${visits.length} زيارات مسجلة لهذا المكان</p></div></div>${visits.length?visits.map((v,index)=>visitBlock(v,index,edit)).join(''):`<div class="notice">لم تسجل زيارة بعد. ${edit?'أضف أول زيارة لتبدأ تقييم الأصناف.':''}</div>`}${edit?`<hr class="hr">${btn(ico('trash')+' حذف المكان وجميع زياراته','delete-place','danger',`data-id="${escape(id)}"`)}`:''}`,'كل زيارة بقصتها وفاتورتها')}
 if(which==='profile'){if(!requiredLogin())return;const p=state.me;return showModal('تعديل حسابي',`<form id="profileForm">${field('profileName','الاسم الظاهر','text',p.display_name||'','required maxlength="80"')}${field('profileUsername','اسم المستخدم','text',p.username||'','required minlength="3" maxlength="24" pattern="[a-z0-9_]{3,24}"')}${field('profileBio','وصف قصير عنك','text',p.bio||'','maxlength="220"')}${fileInput('profilePhoto','صورتك الشخصية — اختياري')}<div class="modal-actions"><button type="submit" class="btn primary wide">حفظ الملف</button></div></form>`)}
 if(which==='settings'){if(!requiredLogin())return;const p=state.me;return showModal('الإعدادات والخصوصية',`<div class="subsection"><h3>رابط صفحتك العام</h3><p class="muted-small">${prettyUrl(p)} — الرابط الظاهري للعرض، أما النسخ فيستخدم رابطًا فعليًا يعمل لدى الجميع.</p>${field('publicSlug','تخصيص رابطك','text',p.public_slug||'','pattern="[a-z0-9_-]{4,40}" minlength="4" maxlength="40"')}${btn('حفظ الرابط','save-slug','primary sm')}</div><div class="subsection"><h3>بياناتك ومزامنتك</h3><p class="muted-small">حسابك متصل بقاعدة البيانات؛ عند الحفظ تظهر تغييراتك في أجهزتك الأخرى. الـRefresh يجلب البيانات فقط ولا يثبّت نسخة جديدة.</p>${btn('مزامنة البيانات الآن','refresh','outline')}${btn('تصدير نسخة احتياطية','backup','outline')}</div><div class="subsection"><h3>الإصدار والتحديثات</h3><div class="notice">هذه معاينة v${APP_VERSION}، وليست تحديثًا مثبتًا. ذواق الرسمي لا يتغير عند فتحها. سيبقى النشر النهائي بقرار المالك.</div></div>`,'تحكّم واضح بدون إعدادات مبعثرة')}
 if(which==='admin'){if(!admin())return;return showModal('إدارة منصة ذواق',`<p class="muted-small">حسابات المستخدمين المعتمدين. إنشاء حساب جديد متاح للمالك فقط.</p><div class="overflow-x"><table class="data-table"><thead><tr><th>المستخدم</th><th>الصلاحية</th><th>الحالة</th></tr></thead><tbody>${state.people.map(p=>`<tr><td>${escape(p.display_name)}<br><small>@${escape(p.username)}</small></td><td>${p.role==='admin'?'مالك':'مستخدم'}</td><td><span class="pill">${p.is_active?'نشط':'موقوف'}</span>${p.id!==state.me.id?btn(p.is_active?'إيقاف':'تفعيل','toggle-user','outline sm',`data-id="${escape(p.id)}"`):''}</td></tr>`).join('')}</tbody></table></div><hr class="hr">${btn(ico('plus')+' إنشاء مستخدم','admin-new-user','primary')}`,'صلاحيات أصحاب الحسابات محفوظة')}
 if(which==='admin-new'){if(!admin())return;return showModal('إنشاء مستخدم معتمد',`<form id="adminNewForm">${field('newDisplay','الاسم المعروض','text','','required maxlength="80"')}${field('newUsername','اسم المستخدم (إنجليزي)','text','','required minlength="3" maxlength="24" pattern="[a-z0-9_]{3,24}"')}${field('newEmail','البريد الإلكتروني','email','','required')}${field('newPassword','كلمة مرور مبدئية لا تقل عن 8 أحرف','password','','required minlength="8"')}<div class="modal-actions"><button class="btn primary wide" type="submit">إنشاء الحساب</button></div></form>`)}
}
function visitBlock(v,index,edit){const it=visitItems(v.id);return `<div class="visit-panel"><div class="visit-head"><div><strong>زيارة ${index+1} · ${dt(v.visited_at)}</strong><span class="muted-small">${it.length} صنف في هذه الزيارة</span></div><span class="pill">${money(visitTotal(v))}</span></div>${it.length?it.map(i=>`<div class="item-line"><div class="item-photo">${i.photo_url?`<img src="${escape(i.photo_url)}" alt="${escape(i.name)}"/>`:'🍽️'}</div><div class="item-info"><b>${escape(i.name)}</b><small>★ ${num(i.rating).toFixed(1)} · ${escape(i.notes||'بدون ملاحظة')}</small></div><b>${money(i.price)}</b>${edit?`<button class="icon-button" style="height:34px;width:34px" data-action="edit-item" data-id="${escape(i.id)}" aria-label="تعديل الصنف">${ico('edit',14)}</button>`:''}</div>`).join(''):`<div class="notice" style="margin-top:10px">لم تضف أصنافًا لهذه الزيارة.</div>`}<div class="price-split"><span>مجموع الأصناف</span><b>${money(subtotal(v))}</b></div>${v.tax_enabled?`<div class="price-split"><span>ضريبة ${num(v.tax_rate||5)}%</span><b>${money(visitTotal(v)- (v.total_override!==null?num(v.total_override):subtotal(v)))}</b></div>`:''}<div class="price-split total"><span>إجمالي الزيارة</span><span>${money(visitTotal(v))}</span></div><div class="visit-actions">${edit?btn(ico('plus',16)+' إضافة صنف','new-item','primary sm',`data-id="${escape(v.place_id)}" data-visit="${escape(v.id)}"`):''}${edit?btn('🧾 الفاتورة','receipt','outline sm',`data-id="${escape(v.id)}"`):''}${v.receipt_url?`<a class="btn soft sm" href="${escape(v.receipt_url)}" target="_blank" rel="noopener">عرض الفاتورة ↗</a>`:''}${edit?btn(ico('trash',13),'delete-visit','ghost sm',`data-id="${escape(v.id)}"`):''}</div></div>`}
const pause=ms=>new Promise(r=>setTimeout(r,ms));
async function getRows(table){if(!sup)return [];const collected=[];for(let i=0;i<12;i++){const {data,error}=await sup.from(table).select('*').range(i*500,i*500+499);if(error)throw error;collected.push(...(data||[]));if((data||[]).length<500)break}return collected}
async function loadData({silent=false}={}){if(!sup){state.online=false;throw new Error('تعذر الاتصال بقاعدة البيانات، حاول لاحقًا')}const [profiles,places,visits,items]=await Promise.all(['profiles','places','visits','items'].map(getRows));state.people=profiles;state.places=places;state.visits=visits;state.items=items;state.me=state.session?profiles.find(x=>x.id===state.session.user.id)||null:null;await loadFavorites();if(!silent)render()}
async function loadFavorites(){let cached=[];try{cached=JSON.parse(localStorage.getItem(FAV_KEY)||'[]')}catch{}state.likes=new Set(cached);if(!sup||!state.me)return;try{const {data,error}=await sup.from('saved_places').select('place_id').eq('owner_id',state.me.id);if(!error){state.likes=new Set((data||[]).map(x=>x.place_id));state.favLoaded=true;localStorage.setItem(FAV_KEY,JSON.stringify([...state.likes]))}}catch{}}
async function toggleFavorite(id){if(!state.me)return alertToast('سجّل دخولك عشان تحفظ المفضلة على حسابك');const yes=!state.likes.has(id);if(yes)state.likes.add(id);else state.likes.delete(id);localStorage.setItem(FAV_KEY,JSON.stringify([...state.likes]));if(sup&&state.online){try{const res=yes?await sup.from('saved_places').upsert({owner_id:state.me.id,place_id:id}):await sup.from('saved_places').delete().eq('owner_id',state.me.id).eq('place_id',id);if(res.error)throw res.error}catch(e){alertToast('تعذرت مزامنة المفضلة، ستبقى محفوظة محليًا') }}render();alertToast(yes?'أضفناه للمفضلة ♡':'أزلناه من المفضلة')}
async function uploadPhoto(input,folder){const file=$(`#${input}`)?.files?.[0];if(!file)return null;if(!state.online)throw new Error('يحتاج رفع الصور إلى اتصال بالإنترنت');if(file.size>16*1024*1024)throw new Error('حجم الصورة كبير؛ اختر صورة لا تتجاوز 16MB');if(!file.type.startsWith('image/')&&!/\.(heic|heif)$/i.test(file.name))throw new Error('اختر صورة صالحة');let blob=file;try{const bmp=await createImageBitmap(file);const size=Math.min(1,1600/Math.max(bmp.width,bmp.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bmp.width*size);canvas.height=Math.round(bmp.height*size);canvas.getContext('2d').drawImage(bmp,0,0,canvas.width,canvas.height);blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.82))||file;bmp.close?.()}catch(e){if(!file.type.startsWith('image/'))throw new Error('صيغة الصورة غير مدعومة في هذا المتصفح. استخدم JPG أو PNG.')}const ext=blob.type==='image/jpeg'?'jpg':(blob.type.split('/')[1]||'png');const path=`${state.me.id}/${folder}/${Date.now()}-${crypto.randomUUID()}.${ext}`;const {error}=await sup.storage.from('blog-media').upload(path,blob,{contentType:blob.type||'image/jpeg'});if(error)throw error;return sup.storage.from('blog-media').getPublicUrl(path).data.publicUrl}
function setBusy(form,on){state.busy=on;$$('button[type="submit"]',form).forEach(b=>{b.disabled=on;b.dataset.label||=(b.textContent||'');b.textContent=on?'جاري الحفظ…':b.dataset.label})}
async function safeSave(form,fn){if(state.busy)return;setBusy(form,true);try{if(!READY)throw new Error('الاتصال بقاعدة Supabase غير مهيأ');if(!navigator.onLine)throw new Error('أنت دون اتصال. المسودة محفوظة ويمكنك إكمالها عند عودة الإنترنت.');await fn()}catch(err){console.error(err);alertToast('تعذر الحفظ: '+(err.message||'خطأ غير متوقع'))}finally{setBusy(form,false)}}
function formValue(id){return String($(`#${id}`)?.value||'').trim()}
async function login(form){await safeSave(form,async()=>{const identifier=formValue('loginIdentifier'),password=formValue('loginPassword');if(!identifier||!password)throw new Error('أدخل بيانات الدخول');localStorage.setItem('thawaqV3Remember', $('#loginRemember').checked?'1':'0');const res=await fetch(`${SURL}/functions/v1/login-identifier`,{method:'POST',headers:{'Content-Type':'application/json','apikey':SKEY},body:JSON.stringify({action:'login',identifier,password})});const body=await res.json();if(!res.ok||!body?.session){const x={EMAIL_NOT_CONFIRMED:'لازم تفعّل البريد الإلكتروني أولًا',ACCOUNT_DISABLED:'حسابك موقوف، تواصل مع المالك',INVALID_CREDENTIALS:'اسم المستخدم أو كلمة المرور غير صحيحة',RATE_LIMIT:'محاولات كثيرة، حاول لاحقًا'};throw new Error(x[body?.code]||'تعذر تسجيل الدخول')}const {data,error}=await sup.auth.setSession({access_token:body.session.access_token,refresh_token:body.session.refresh_token});if(error)throw error;state.session=data.session;await loadData({silent:true});closeModal();state.tab='home';render();alertToast('حيّاك في ذواق ✨')})}
async function savePlace(form){await safeSave(form,async()=>{if(!requiredLogin())return;const id=form.dataset.id;const old=state.places.find(p=>p.id===id);if(old&&!own(old))throw new Error('لا توجد صلاحية تعديل');const name=formValue('placeName'),city=formValue('placeCity'),type=formValue('placeType'),notes=formValue('placeNotes');if(!name||!city||!['restaurant','cafe','tea'].includes(type))throw new Error('اسم المكان والمدينة والتصنيف مطلوبة');const photo=await uploadPhoto('placePhoto','covers'),payload={name,city,type,notes,...photo?{cover_url:photo}:{}};let placeId=id;
 if(old){const {error}=await sup.from('places').update(payload).eq('id',id);if(error)throw error;}else{const {data,error}=await sup.from('places').insert({...payload,owner_id:state.me.id}).select('id').single();if(error)throw error;placeId=data.id;const {data:visit,error:ve}=await sup.from('visits').insert({place_id:placeId,owner_id:state.me.id,visited_at:new Date().toISOString()}).select('id').single();if(ve)throw ve;const quickName=formValue('quickItemName');if(quickName){const {error:ie}=await sup.from('items').insert({place_id:placeId,visit_id:visit.id,owner_id:state.me.id,name:quickName,price:Math.max(0,decimal(formValue('quickItemPrice'))),rating:4.5});if(ie)alertToast('تم حفظ المكان، لكن تعذر حفظ الصنف؛ يمكنك إضافته يدويًا')}}
 localStorage.removeItem(STORAGE_DRAFT);closeModal();await loadData({silent:true});render();openModal('detail',placeId);alertToast(old?'تم تعديل المكان':'تم حفظ تجربتك الأولى ✨')})}
async function saveItem(form){await safeSave(form,async()=>{const place=state.places.find(p=>p.id===form.dataset.place),visit=state.visits.find(v=>v.id===form.dataset.visit),id=form.dataset.id,old=state.items.find(x=>x.id===id);if(!place||!visit||!own(place))throw new Error('لا توجد صلاحية');const name=formValue('itemName'),price=num(formValue('itemPrice')),rt=num($('#ratingValue').value),notes=formValue('itemNotes');if(!name||price<0||rt<1||rt>5)throw new Error('الاسم والسعر والتقييم مطلوبة');const image=await uploadPhoto('itemPhoto','items'),payload={name,price,rating:rt,notes,...image?{photo_url:image}:{}};let result;if(old)result=await sup.from('items').update(payload).eq('id',id);else result=await sup.from('items').insert({...payload,place_id:place.id,visit_id:visit.id,owner_id:state.me.id});if(result.error)throw result.error;await loadData({silent:true});render();openModal('detail',place.id);alertToast('تم حفظ الصنف وتقييمه ⭐')})}
async function saveReceipt(form){await safeSave(form,async()=>{const id=form.dataset.id,visit=state.visits.find(v=>v.id===id),place=state.places.find(p=>p.id===visit?.place_id);if(!visit||!own(place))throw new Error('لا توجد صلاحية');const photo=await uploadPhoto('receiptPhoto','receipts'),total=formValue('receiptTotal'),{error}=await sup.from('visits').update({total_override:total===''?null:num(total),tax_enabled:$('#receiptTax').checked,tax_rate:5,...photo?{receipt_url:photo}:{}}).eq('id',id);if(error)throw error;await loadData({silent:true});render();openModal('detail',place.id);alertToast('تم حفظ فاتورة الزيارة')})}
async function saveProfile(form){await safeSave(form,async()=>{const display_name=formValue('profileName'),username=formValue('profileUsername').toLowerCase(),bio=formValue('profileBio');if(!display_name||!/^[a-z0-9_]{3,24}$/.test(username))throw new Error('تحقق من الاسم واسم المستخدم الإنجليزي');const photo=await uploadPhoto('profilePhoto','avatars'),{error}=await sup.from('profiles').update({display_name,username,bio,...photo?{avatar_url:photo}:{}}).eq('id',state.me.id);if(error)throw error;await loadData({silent:true});closeModal();render();alertToast('تم تحديث حسابك')})}
async function adminCreateUser(form){await safeSave(form,async()=>{if(!admin())throw new Error('ليس لديك صلاحيات المالك');const {data:{session}}=await sup.auth.getSession();if(!session)throw new Error('سجّل الدخول أولًا');const res=await fetch(`${SURL}/functions/v1/admin-users`,{method:'POST',headers:{'Content-Type':'application/json',apikey:SKEY,authorization:`Bearer ${session.access_token}`},body:JSON.stringify({action:'create',display_name:formValue('newDisplay'),username:formValue('newUsername'),email:formValue('newEmail'),password:$('#newPassword').value})}),response=await res.json();if(!res.ok||!response.ok)throw new Error(response.error==='USERNAME_TAKEN'?'اسم المستخدم مستخدم مسبقًا':response.error==='EMAIL_TAKEN'?'البريد مستخدم مسبقًا':'تعذر إنشاء الحساب');await loadData({silent:true});openModal('admin');alertToast('تم إنشاء المستخدم المعتمد')})}
async function addVisit(placeId){if(!requiredLogin())return;const p=state.places.find(x=>x.id===placeId);if(!p||!own(p))return;const go=confirm(`إضافة زيارة جديدة اليوم إلى ${p.name}؟\nكل زيارة لها أصناف وفاتورة خاصة.`);if(!go)return;try{const {error}=await sup.from('visits').insert({place_id:placeId,owner_id:state.me.id,visited_at:new Date().toISOString()});if(error)throw error;await loadData({silent:true});render();openModal('detail',placeId);alertToast('أضفنا زيارة جديدة، تقدر تضيف أصنافها الآن')}catch(e){alertToast('تعذر إضافة الزيارة: '+e.message)}}
async function deleteVisit(id){const v=state.visits.find(x=>x.id===id),p=state.places.find(x=>x.id===v?.place_id);if(!v||!own(p)||!confirm('حذف هذه الزيارة وجميع أصنافها؟ لا يمكن التراجع.'))return;try{let r=await sup.from('items').delete().eq('visit_id',id);if(r.error)throw r.error;r=await sup.from('visits').delete().eq('id',id);if(r.error)throw r.error;await loadData({silent:true});render();openModal('detail',p.id);alertToast('تم حذف الزيارة')}catch(e){alertToast('تعذر الحذف: '+e.message)}}
async function deleteItem(id){const it=state.items.find(x=>x.id===id),p=state.places.find(x=>x.id===it?.place_id);if(!it||!own(p)||!confirm('حذف هذا الصنف وتقييمه نهائيًا؟'))return;try{const {error}=await sup.from('items').delete().eq('id',id);if(error)throw error;await loadData({silent:true});render();openModal('detail',p.id);alertToast('تم حذف الصنف')}catch(e){alertToast('تعذر حذف الصنف: '+e.message)}}
async function toggleUser(id){if(!admin()||id===state.me.id)return;const u=state.people.find(x=>x.id===id);if(!u||!confirm(`${u.is_active?'إيقاف':'تفعيل'} حساب ${u.display_name}؟`))return;try{const {error}=await sup.from('profiles').update({is_active:!u.is_active}).eq('id',id);if(error)throw error;await loadData({silent:true});render();openModal('admin');alertToast('تم تحديث صلاحية المستخدم')}catch(e){alertToast('تعذر تغيير حالة الحساب: '+e.message)}}
async function deletePlace(id){const p=state.places.find(x=>x.id===id);if(!p||!own(p)||!confirm(`حذف «${p.name}» وجميع زياراته وأصنافه نهائيًا؟ لا يمكن التراجع.`))return;try{let r=await sup.from('items').delete().eq('place_id',id);if(r.error)throw r.error;r=await sup.from('visits').delete().eq('place_id',id);if(r.error)throw r.error;r=await sup.from('places').delete().eq('id',id);if(r.error)throw r.error;closeModal();await loadData({silent:true});render();alertToast('تم حذف المكان')}catch(e){alertToast('تعذر الحذف: '+e.message)}}
async function copyShare(p){const u=shareUrl(p);try{await navigator.clipboard.writeText(u);alertToast('تم نسخ رابط المشاركة الحقيقي')}catch{window.prompt('انسخ رابط المشاركة الحقيقي:',u)}}
async function shareMe(){const p=state.me;if(!p)return;const url=shareUrl(p);try{if(navigator.share)await navigator.share({title:`ذوق ${p.display_name} — ذواق`,text:'تجربتي للأماكن على ذواق',url});else await copyShare(p)}catch(e){if(e.name!=='AbortError')await copyShare(p)}}
async function saveSlug(){if(!state.me)return;const slug=formValue('publicSlug').toLowerCase();if(!/^[a-z0-9_-]{4,40}$/.test(slug))return alertToast('الرابط 4–40 حرفًا من الإنجليزي والأرقام - أو _');try{const {error}=await sup.from('profiles').update({public_slug:slug}).eq('id',state.me.id);if(error)throw error;await loadData({silent:true});closeModal();render();alertToast('تم تحديث رابط المشاركة، والرابط القديم لم يعد صالحًا')}catch(e){alertToast('لم يُحفظ الرابط، قد يكون مستخدمًا بالفعل')}}
function backup(){if(!state.me)return requiredLogin();const id=state.me.id,p=state.me.role==='admin',ids=new Set(state.places.filter(x=>p||x.owner_id===id).map(x=>x.id)),payload={app:'THAWAQ',version:APP_VERSION,exported_at:new Date().toISOString(),note:'الصور محفوظة كرابط URL. هذا الملف ليس نسخة مستقلة من الصور أو كلمات المرور.',profiles:p?state.people:[state.me],places:state.places.filter(x=>ids.has(x.id)),visits:state.visits.filter(x=>ids.has(x.place_id)),items:state.items.filter(x=>ids.has(x.place_id)),saved_places:[...state.likes]};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`thawaq-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),4000);alertToast('نسختك الاحتياطية جاهزة للتحميل')}
async function refresh(){if(!READY)return alertToast('اتصال Supabase غير جاهز');try{await loadData({silent:true});render();alertToast('تم تحديث بياناتك ✓ بدون تحديث إصدار التطبيق')}catch(e){alertToast('تعذرت المزامنة: '+e.message)}}
async function logout(){if(!confirm('هل أنت متأكد من تسجيل الخروج؟'))return;await sup?.auth.signOut();state.session=null;state.me=null;state.tab='home';state.likes=new Set();closeModal();render();alertToast('تم تسجيل الخروج')}
function collectPreview(input){const id=input.id+'Preview',img=$('#'+id);if(!img)return;const f=input.files?.[0];if(!f){img.classList.add('hidden');return}img.src=URL.createObjectURL(f);img.classList.remove('hidden')}
function updateResults(){if(state.tab!=='discover')return;const rows=getFilters(state.places);const holder=$('#filteredGrid'),counter=$('#resultsCount');if(holder)holder.innerHTML=rows.map(placeTile).join('')||'<div class="empty-state card"><h3>ما لقينا نتائج</h3><p>جرّب بحث مختلف.</p></div>';if(counter)counter.textContent=`${rows.length} مكان في نتائج البحث`}
function navigate(id){closeModal();if(id==='diary'||id==='insights'||id==='account'){}state.tab=id;state.publicMode=false;history.replaceState({},'',location.pathname);render()}
async function handleAction(el){const act=el.dataset.action,id=el.dataset.id;switch(act){case 'close-modal':closeModal();break;case 'new-place':openModal('place');break;case 'login':openModal('login');break;case 'go-discover':navigate('discover');break;case 'diary-favs':navigate('diary');state.diaryFilter='favorites';render();break;case 'favorite':await toggleFavorite(id);break;case 'new-item':openModal('item',id,{visitId:el.dataset.visit});break;case 'edit-item':{const item=state.items.find(x=>x.id===id);if(item)openModal('item',item.place_id,{visitId:item.visit_id,itemId:id});break}case 'edit-place':openModal('place',id);break;case 'receipt':openModal('receipt',id);break;case 'add-visit':await addVisit(id);break;case 'delete-visit':await deleteVisit(id);break;case 'delete-item':await deleteItem(id);break;case 'toggle-user':await toggleUser(id);break;case 'delete-place':await deletePlace(id);break;case 'maps':{const p=state.places.find(x=>x.id===id);if(p)window.open(`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.name+', '+p.city+', UAE')}`,'_blank','noopener');break}case 'share-me':await shareMe();break;case 'copy-me':if(state.me)await copyShare(state.me);break;case 'settings':openModal('settings');break;case 'edit-profile':openModal('profile');break;case 'save-slug':await saveSlug();break;case 'admin-users':openModal('admin');break;case 'admin-new-user':openModal('admin-new');break;case 'refresh':await refresh();break;case 'backup':backup();break;case 'logout':await logout();break;case 'exit-share':state.shareSlug=null;state.publicMode=false;navigate('home');break}}
async function handleSubmit(form){if(form.id==='loginForm')return login(form);if(form.id==='placeForm')return savePlace(form);if(form.id==='itemForm')return saveItem(form);if(form.id==='receiptForm')return saveReceipt(form);if(form.id==='profileForm')return saveProfile(form);if(form.id==='adminNewForm')return adminCreateUser(form)}
function wire(){document.addEventListener('click',async e=>{const star=e.target.closest('[data-star]');if(star){const n=num(star.dataset.star);$('#ratingValue').value=n;$('#starValue').textContent=n.toFixed(1)+'/5';$$('[data-star]').forEach(b=>b.classList.toggle('selected',num(b.dataset.star)<=n));return}const cho=e.target.closest('[data-choice]');if(cho){$('#placeType').value=cho.dataset.choice;$$('[data-choice]').forEach(b=>b.classList.toggle('active',b===cho));return}const nav=e.target.closest('[data-tab]');if(nav){navigate(nav.dataset.tab);return}const action=e.target.closest('[data-action]');if(action){e.preventDefault();await handleAction(action);return}const item=e.target.closest('[data-place]');if(item)openModal('detail',item.dataset.place)});
 document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-place]')){e.preventDefault();openModal('detail',e.target.dataset.place)}});
 document.addEventListener('submit',e=>{if(e.target.matches('form')){e.preventDefault();handleSubmit(e.target)}});
 document.addEventListener('change',e=>{if(e.target.matches('input[type=file]'))collectPreview(e.target);if(e.target.id==='cityFilter'||e.target.id==='sortFilter'){state.filter[e.target.id==='cityFilter'?'city':'sort']=e.target.value;updateResults()}});
 document.addEventListener('input',e=>{if(e.target.id==='searchPlaces'){state.filter.q=e.target.value;updateResults()}if(e.target.closest('#placeForm')&&e.target.type!=='file'){const form=$('#placeForm');if(!form.dataset.id){localStorage.setItem(STORAGE_DRAFT,JSON.stringify({name:formValue('placeName'),city:formValue('placeCity'),type:formValue('placeType'),notes:formValue('placeNotes'),quickItem:formValue('quickItemName'),quickPrice:formValue('quickItemPrice')}))}}});
 document.addEventListener('click',e=>{const chip=e.target.closest('[data-type]');if(chip){state.filter.type=chip.dataset.type;$$('[data-type]').forEach(b=>b.classList.toggle('active',b===chip));updateResults()}const dc=e.target.closest('[data-diary]');if(dc){state.diaryFilter=dc.dataset.diary;render()}});
 $('#refreshBtn').addEventListener('click',refresh);$('#avatarBtn').addEventListener('click',()=>navigate('account'));window.addEventListener('online',()=>{state.online=true;refresh()});window.addEventListener('offline',()=>{state.online=false;render()});window.addEventListener('popstate',()=>{state.shareSlug=new URLSearchParams(location.search).get('share');state.publicMode=!!state.shareSlug;render()});
}
function startClock(){const tick=()=>{const stamp=new Date();const clock=stamp.toLocaleString('ar-AE',{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:true});$('#liveTime').textContent=clock;$('#headerDateRow').textContent=clock};tick();setInterval(tick,1000)}
function connectRealtime(){if(!sup)return;state.channels.forEach(c=>sup.removeChannel(c));state.channels=[];const ch=sup.channel('thawaq-v3-preview-data').on('postgres_changes',{event:'*',schema:'public',table:'places'},onData).on('postgres_changes',{event:'*',schema:'public',table:'items'},onData).on('postgres_changes',{event:'*',schema:'public',table:'visits'},onData).on('postgres_changes',{event:'*',schema:'public',table:'profiles'},onData).subscribe();state.channels.push(ch)}
let nextSync=null;function onData(){clearTimeout(nextSync);nextSync=setTimeout(async()=>{try{await loadData({silent:true});if(!$('#modalLayer').classList.contains('show'))render();else state.needsRefresh=true}catch{}},1300)}
async function init(){wire();startClock();state.publicMode=!!state.shareSlug;try{if(!sup)throw new Error('مفتاح Supabase غير متوفر؛ تأكد من وجود config.js بجوار ملف المعاينة.');const {data:{session}}=await sup.auth.getSession();state.session=session;await loadData({silent:true});connectRealtime();sup.auth.onAuthStateChange((ev,newSession)=>{const oldId=state.session?.user?.id,newId=newSession?.user?.id;state.session=newSession;if(oldId!==newId){Promise.resolve().then(()=>loadData({silent:true})).then(render).catch(console.error)}})}catch(e){console.error(e);state.online=false;alertToast('تعذر تحميل بيانات ذواق؛ تحقق من الاتصال')}
 render();const draft=localStorage.getItem(STORAGE_DRAFT);if(draft&&state.me){$('#previewTop').title='عند فتح تجربة جديدة، يمكنك استعادة المسودة المحفوظة';}
}
init();
})();
